// Generated by scripts/sync-core.mts from packages/core/src. Do not edit; run `pnpm sync:core`.
import type { Block, LessonSpec } from "./schema.ts";

// Inline maths in lesson text ($x^2$). The server pre-renders each formula with KaTeX when the
// lesson is saved (spec.math_html, keyed by the LaTeX source), and the client splits text with the
// same rule, so no KaTeX ships to the browser (02 §7). Tiny and dependency-free: client-safe.

export type InlineSegment = { kind: "text"; text: string } | { kind: "math"; latex: string };

// $…$ with no space just inside either dollar, so "costs $5 and $10" stays text.
const INLINE_MATH = /\$([^\s$](?:[^$]*?[^\s$])?)\$/g;

export function splitInlineMath(text: string): InlineSegment[] {
  const out: InlineSegment[] = [];
  let last = 0;
  for (const m of text.matchAll(INLINE_MATH)) {
    const at = m.index ?? 0;
    if (at > last) out.push({ kind: "text", text: text.slice(last, at) });
    out.push({ kind: "math", latex: m[1]! });
    last = at + m[0].length;
  }
  if (last < text.length) out.push({ kind: "text", text: text.slice(last) });
  return out;
}

/** Every student-visible text field of a block (the fields that may contain inline maths). */
export function blockTexts(block: Block): string[] {
  switch (block.type) {
    case "prose":
    case "callout":
      return [block.md];
    case "reveal":
      return [block.prompt, block.md];
    case "flashcards":
      return block.cards.flatMap((c) => [c.front, c.back]);
    case "compare":
      return [block.left.title, ...block.left.points, block.right.title, ...block.right.points];
    case "table":
      return [...block.columns, ...block.rows.flat()];
    case "timeline":
      return block.events.flatMap((e) => [e.when, e.label, e.detail ?? ""]);
    case "stepper":
      return block.steps.map((s) => s.why);
    case "plot":
      return [block.caption ?? ""];
    case "diagram":
      return [block.caption ?? "", ...block.nodes.map((n) => n.label), ...block.edges.map((e) => e.label ?? "")];
    case "checkpoint": {
      const item = block.item;
      const common = [item.stem_md, "why" in item ? item.why : ""];
      if (item.type === "mcq") return [...common, ...item.options.flatMap((o) => [o.md, o.why])];
      if (item.type === "order") return [...common, ...item.steps];
      if (item.type === "match") return [...common, ...item.pairs.flat()];
      return common;
    }
    default:
      return [];
  }
}

export function lessonTexts(spec: LessonSpec): string[] {
  return [spec.objective, ...spec.summary, ...spec.screens.flatMap((s) => s.blocks.flatMap(blockTexts))].filter(
    Boolean,
  );
}

/** The distinct inline formulas a lesson uses. */
export function collectInlineMath(spec: LessonSpec): string[] {
  const set = new Set<string>();
  for (const text of lessonTexts(spec)) {
    for (const seg of splitInlineMath(text)) if (seg.kind === "math") set.add(seg.latex);
  }
  return [...set];
}

/**
 * A math block's `latex` is already math mode. Models sometimes wrap it in \( \), \[ \], $ or $$,
 * which KaTeX rejects; remove one outer pair so the formula renders as written.
 */
export function stripMathDelimiters(latex: string): string {
  const t = latex.trim();
  const m =
    t.match(/^\\\(([\s\S]*)\\\)$/) ??
    t.match(/^\\\[([\s\S]*)\\\]$/) ??
    t.match(/^\$\$([\s\S]*)\$\$$/) ??
    t.match(/^\$([^$][\s\S]*)\$$/);
  return m ? m[1]!.trim() : t;
}
